const copy = global.get("s3copy");
const { from, to } = msg.payload;
const log = { info: m => node.log(m), warn: m => node.warn(m), error: m => node.error(m) };

copy(from, to, { log })
    .then(res => { msg.payload = res; node.send(msg); })
    .catch(err => node.error(err.message, msg));
return;
